package com.samadhansetu.controller;
import com.samadhansetu.Service.UniversityService; import com.samadhansetu.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/universities") @RequiredArgsConstructor public class UniversityController{private final UniversityService service; @PostMapping public ResponseEntity<UniversityResponseDto> create(@RequestBody UniversityRequestDto r){return ResponseEntity.status(HttpStatus.CREATED).body(service.createUniversity(r));}@GetMapping public List<UniversityResponseDto> all(){return service.getAllUniversities();}@GetMapping("/{id}") public UniversityResponseDto get(@PathVariable Long id){return service.getUniversityById(id);}@PutMapping("/{id}") public UniversityResponseDto update(@PathVariable Long id,@RequestBody UniversityRequestDto r){return service.updateUniversity(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.deleteUniversity(id);return ResponseEntity.noContent().build();}@GetMapping("/search") public List<UniversityResponseDto> search(@RequestParam String name){return service.searchByName(name);}@GetMapping("/location") public List<UniversityResponseDto> location(@RequestParam String value){return service.searchByLocation(value);}}
